import{_ as t,o as a,c as n,ak as i}from"./chunks/framework.B8jO0odJ.js";const h=JSON.parse('{"title":"Chainy manuscript and pre-final evidence","description":"Capstone project title: Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain & AI)","frontmatter":{"title":"Chainy manuscript and pre-final evidence","description":"Capstone project title: Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain & AI)","source":"docs/manuscript-evidence-map.md","category":"Research & evaluation","sourceUpdated":"2026-10-08T07:30:14+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/manuscript-evidence-map.md","filePath":"content/docs/manuscript-evidence-map.md"}'),r={name:"content/docs/manuscript-evidence-map.md"};function o(s,e,d,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-manuscript-and-pre-final-evidence">Chainy manuscript and pre-final evidence<a class="header-anchor" href="#chainy-manuscript-and-pre-final-evidence" aria-label="Link to this section">​</a></h1><p><strong>Capstone project title:</strong> Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain &amp; AI)</p><p>The user supplied the official manuscript outline and three mandatory pre-final requirements on October 5, 2026. November 21 requires (1) manuscript formatting and chapters complete, (2) core system modules functional, and (3) necessary pilot-area evidence/documents. Treat missing required evidence as a blocker, not an optional gap.</p><p>The actual scoring criterion descriptions and what level of evaluation is accepted at pre-final are still unspecified. The user subsequently answered yes both; plan for preliminary and system evaluation evidence. Named contact, formal booking and instruments remain to be supplied. The table of contents is not itself a weighted scoring rubric.</p><h2 id="official-outline-supplied-by-the-user">Official outline supplied by the user<a class="header-anchor" href="#official-outline-supplied-by-the-user" aria-label="Link to this section">​</a></h2><p>Front matter: title/system page, approval sheet, acknowledgement, executive summary, table of contents, list of tables, list of figures.</p><ol><li>INTRODUCTION: 1.1 Project Context; 1.2 Purpose and Description; 1.3 Objectives of the Study; 1.4 Scope and Delimitation; 1.5 Significance of the Study.</li><li>REVIEW OF RELATED LITERATURE: 2.1 Related Studies &amp; Literature; 2.2 Technical Background; 2.3 Definition of terms.</li><li>DESIGN AND METHODOLOGY: 3.1 Research Methodology and Design; 3.2 System Development Methodology; 3.2.1 Requirement Analysis; 3.2.2 Requirement Documentation; 3.2.2.1 Software Requirements; 3.2.2.2 Hardware Requirements; 3.2.2.3 Data; 3.2.3 Design of Software; 3.2.4 Development and Testing; 3.2.5 Description of the Prototype; 3.2.6 Implementation Plan; 3.3 Respondents &amp; Population; 3.4 Evaluation Tool; 3.4.1 Statistical tools; 3.4.2 ISO 2010 System Evaluation tools.</li><li>RESULTS AND DISCUSSION: 4.1 Preliminary Evaluation Results; 4.2 System Evaluation Results.</li><li>CONCLUSIONS AND RECOMMENDATIONS: 5.1 Conclusion; 5.2 Recommendations. REFERENCES. APPENDICES: A Relevant Source Code; B Evaluation Tool or Test Documents; C Sample input/Output/Reports; D Users Guide; E Process/Data/Information Flow; F Screen Layout; G Test Results; H Sample Generated Output; I Pictures showcasing the data gathering, investigation done; J One-Page Curriculum Vitae; K Letters/Turnitin Certification; L User Acceptance Testing (UAT); M Memorandum of Understanding (MOU).</li></ol><p>The phrase ISO 2010 is preserved as supplied. Its intended standard/version or school instrument needs clarification; do not silently rename it.</p><h2 id="evidence-ownership-and-completion">Evidence ownership and completion<a class="header-anchor" href="#evidence-ownership-and-completion" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Work</th><th>Owner and support</th><th>Task</th><th>Completion evidence</th></tr></thead><tbody><tr><td>Chapters I–II</td><td>Sean; Miguel formatting support</td><td>CH-22</td><td>Reviewed narrative, verified literature and consistent current scope</td></tr><tr><td>Chapter III</td><td>Sean; Christian technical input</td><td>CH-23</td><td>Methods, requirements/design, respondents and evaluation instruments</td></tr><tr><td>Pilot documents</td><td>Sherwin; Sean research coordination</td><td>CH-24/CH-12</td><td>Actual site permissions, required letters/MOU, scheduling and protocol</td></tr><tr><td>Working modules</td><td>Christian; Sherwin AI, Luis art, Miguel UI</td><td>CH-03–14/CH-26</td><td>Reproducible device build and requirement-specific test records</td></tr><tr><td>Chapters IV–V</td><td>Sean; Miguel evidence assembly</td><td>CH-15/CH-25</td><td>Actual preliminary/system evaluation results and justified conclusions</td></tr><tr><td>Front matter and references</td><td>Sean; Miguel support</td><td>CH-16/CH-25</td><td>Required format, citations, contents and lists verified</td></tr><tr><td>Appendices A/E/F/G/H</td><td>Christian; Miguel support</td><td>CH-25</td><td>Source extracts, flows, layouts, tests and outputs</td></tr><tr><td>Appendices B/C/D</td><td>Sean; technical/educator review</td><td>CH-25</td><td>Instruments, sample records and user guide</td></tr><tr><td>Appendices I/J/K/L/M</td><td>Sean; team and site contributors</td><td>CH-24/CH-25</td><td>Authorized evidence, CVs, actual letters/certification, UAT and MOU as required</td></tr></tbody></table><p>No appendix is declared complete merely because a heading exists. Confirm which externally issued documents are required by pre-final and obtain them early. Photos, identity-bearing forms and raw participant data belong in the approved restricted evidence store, not GitHub. Repository records should hold redacted summaries or approved references.</p><h2 id="schedule-implication">Schedule implication<a class="header-anchor" href="#schedule-implication" aria-label="Link to this section">​</a></h2><p>Prepare site arrangements by October 12 and methods/instruments by October 16–18. The October 8 conditional forecast targets an integrated beta candidate by October 30, readiness checks October 31–November 2, and possible user beta testing November 3–6 at Tambunan National High School, Marinduque. These replace the previous November 6 integration / November 7 readiness / November 8–13 collection proposal. Booking, learner/session details and approved collection remain unresolved. Use November 7–13 for actual evidence analysis, fixes and regression, then finalize the manuscript by November 16 and rehearse November 17–20 for the November 21 pre-final. Beta usability feedback alone does not establish that all school evaluation requirements are met. This is a conditional forecast, not verified capacity or completed school evidence; missed readiness requires rescheduling or an explicitly agreed scope, never invented data.</p><h2 id="available-drafting-references">Available drafting references<a class="header-anchor" href="#available-drafting-references" aria-label="Link to this section">​</a></h2><p>Use the <a href="/Chainy-Docs/content/docs/manuscript-working-draft.html">manuscript working draft</a>, <a href="/Chainy-Docs/content/docs/game-design.html">GDD</a>, <a href="/Chainy-Docs/content/docs/technical-design.html">architecture</a>, <a href="/Chainy-Docs/content/docs/hardware-validation.html">hardware plan</a>, <a href="/Chainy-Docs/content/docs/qa-evaluation.html">QA protocol</a>, <a href="/Chainy-Docs/content/docs/user-guide.html">draft guide</a> and <a href="/Chainy-Docs/content/docs/team-delegation.html">team assignments</a> as consistent source material. These are design/draft artifacts, not evidence of completed implementation or participant results. English first is confirmed; the exact ISO instrument remains pending.</p></div>',1)])])}const m=t(r,[["render",o]]);export{h as __pageData,m as default};
